import pathlib,json,datetime,collections
UTC=datetime.timezone.utc
IST=datetime.timezone(datetime.timedelta(hours=5,minutes=30))
def parse(s):
 base=datetime.datetime.strptime(s[:19],'%Y-%m-%dT%H:%M:%S').replace(tzinfo=UTC)
 frac=s[19:].split('Z')[0]
 return base+datetime.timedelta(seconds=float('0'+frac) if frac.startswith('.') else 0)
rows=[json.loads(l) for l in open('/tmp/clanker-kernel-trace-20261010.jsonl')]
api=[r for r in rows if r.get('auth_strategy')=='api_key']
found={}
for p in pathlib.Path('.local/hermes-lab/home').rglob('*.log'):
 for n,l in enumerate(p.open(errors='replace'),1):
  if 'Kernel upstream failure {' not in l or l[:10]<'2026-10-09':continue
  try:d=json.loads(l.split('Kernel upstream failure ',1)[1])
  except:continue
  if d['failure_kind']=='timeout':found.setdefault(d['diagnostic_ref'],(p,n,l[:23],d))
results=[]
for ref,(p,n,s,d) in sorted(found.items(),key=lambda x:x[1][2]):
 end=datetime.datetime.strptime(s,'%Y-%m-%d %H:%M:%S,%f').replace(tzinfo=IST).astimezone(UTC)
 req=d['requests'][-1]; start=end-datetime.timedelta(milliseconds=req['elapsed_ms'])
 route=req['route'].replace('/vaults/{vault}','/vaults/{id_or_name}').replace('/browsers/{id}','/browsers/{id_or_name}').replace('/proxies/{id}','/proxies/{id_or_name}')
 # Kernel audit proxy route uses {id}, normalize both.
 norm=lambda r:r.replace('{id_or_name}','{id}')
 candidates=[]
 for r in api:
  if r['method']!=req['method'] or norm(r['route'])!=norm(route):continue
  ts=parse(r['timestamp']); delta=(ts-start).total_seconds()
