def test_concurrent_operations_keep_their_own_diagnostic_reference(client, caplog, monkeypatch):
    barrier = threading.Barrier(2)
    def failed_request(method, url, **kwargs):
        barrier.wait(timeout=5)
        raise requests.ReadTimeout('Synthetic concurrent timeout; ' + HOSTILE)
    monkeypatch.setattr(client.http, 'request', failed_request)
    def create(task):
        with pytest.raises(AccessError) as caught:
            client.create_session(task)
        return str(caught.value)
    with ThreadPoolExecutor(max_workers=2) as executor:
        outcomes = list(executor.map(create, ('requester-a-task', 'requester-b-task')))
    logged = events(caplog)
    assert len(logged) == 2
    refs = {event['diagnostic_ref'] for event in logged}
    assert len(refs) == 2
    assert len({event['task_ref'] for event in logged}) == 2
    assert all(sum('Reference: ' + ref + '.' in result for result in outcomes) == 1 for ref in refs)
    assert all(event['operation'] == 'create_session' and len(event['requests']) == 1 for event in logged)


